// Worker.cs — compiled to IL inside Worker.dll
Console.WriteLine("consumer up");

// Build:  dotnet build -c Release
// Run:    dotnet Worker.dll

// First calls compile quickly at Tier 0/1 (less optimized).
// Hot methods recompile at Tier 1 Optimized after enough calls.
// Tiered PGO (.NET 7+) uses profile data from earlier tiers.

for (var i = 0; i < 10_000; i++)
    HotPath(i); // JIT may promote this method to optimized tier
